def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    # Parse the range into comparator sets
    if not rng:
        raise ValueError("Invalid range")

    # Split by || to get sets
    sets = rng.split("||")
    sets = [s.strip() for s in sets if s.strip()]

    if not sets:
        raise ValueError("Invalid range")

    # Check if any set satisfies the version
    for set_str in sets:
        if _satisfies_set(version, set_str):
            return True

    return False


def _satisfies_set(version, set_str):
    """Check if a version satisfies a single set of comparators."""
    # Split by whitespace to get individual comparators
    comparators = set_str.split()

    if not comparators:
        raise ValueError("Invalid range")

    # Check if all comparators in the set are satisfied
    for comp in comparators:
        if not _satisfies_comparator(version, comp):
            return False

    return True


def _satisfies_comparator(version, comparator):
    """Check if a version satisfies a single comparator."""
    # Parse the comparator
    if comparator.startswith(">="):
        version_req = comparator[2:]
        return _compare_versions(version, version_req) >= 0
    elif comparator.startswith(">"):
        version_req = comparator[1:]
        return _compare_versions(version, version_req) > 0
    elif comparator.startswith("<="):
        version_req = comparator[2:]
        return _compare_versions(version, version_req) <= 0
    elif comparator.startswith("<"):
        version_req = comparator[1:]
        return _compare_versions(version, version_req) < 0
    elif comparator.startswith("^"):
        version_req = comparator[1:]
        return _satisfies_caret(version, version_req)
    elif comparator.startswith("~"):
        version_req = comparator[1:]
        return _satisfies_tilde(version, version_req)
    elif comparator.startswith("="):
        version_req = comparator[1:]
        return _compare_versions(version, version_req) == 0
    else:
        # No operator means equality
        return _compare_versions(version, comparator) == 0


def _compare_versions(v1, v2):
    """Compare two version strings. Return 1 if v1 > v2, 0 if equal, -1 if v1 < v2."""
    # Parse versions
    v1_parsed = _parse_version(v1)
    v2_parsed = _parse_version(v2)

    # Compare major, minor, patch
    if v1_parsed[0] > v2_parsed[0]:
        return 1
    elif v1_parsed[0] < v2_parsed[0]:
        return -1

    if v1_parsed[1] > v2_parsed[1]:
        return 1
    elif v1_parsed[1] < v2_parsed[1]:
        return -1

    if v1_parsed[2] > v2_parsed[2]:
        return 1
    elif v1_parsed[2] < v2_parsed[2]:
        return -1

    # If we get here, the numeric parts are equal
    # Check prerelease
    if v1_parsed[3] is None and v2_parsed[3] is None:
        return 0
    elif v1_parsed[3] is None:
        return 1
    elif v2_parsed[3] is None:
        return -1
    else:
        # Both have prerelease, compare them
        return _compare_prerelease(v1_parsed[3], v2_parsed[3])


def _parse_version(version_str):
    """Parse a version string into (major, minor, patch, prerelease)."""
    # Check for build metadata
    if "+" in version_str:
        raise ValueError("Build metadata not allowed")

    # Split by - to separate prerelease
    if "-" in version_str:
        main, prerelease = version_str.split("-", 1)
    else:
        main = version_str
        prerelease = None

    # Parse main version
    parts = main.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid version")

    try:
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
    except ValueError:
        raise ValueError("Invalid version")

    # Validate no leading zeros
    if parts[0] != "0" and parts[0].startswith("0"):
        raise ValueError("Invalid version")
    if parts[1] != "0" and parts[1].startswith("0"):
        raise ValueError("Invalid version")
    if parts[2] != "0" and parts[2].startswith("0"):
        raise ValueError("Invalid version")

    return (major, minor, patch, prerelease)


def _compare_prerelease(prerelease1, prerelease2):
    """Compare two prerelease strings."""
    parts1 = prerelease1.split(".")
    parts2 = prerelease2.split(".")

    min_len = min(len(parts1), len(parts2))

    for i in range(min_len):
        p1 = parts1[i]
        p2 = parts2[i]

        # Check if both are numeric
        is_num1 = p1.isdigit()
        is_num2 = p2.isdigit()

        if is_num1 and is_num2:
            # Both numeric, compare numerically
            num1 = int(p1)
            num2 = int(p2)
            if num1 > num2:
                return 1
            elif num1 < num2:
                return -1
        elif is_num1:
            # Numeric is lower than alphanumeric
            return -1
        elif is_num2:
            # Numeric is lower than alphanumeric
            return 1
        else:
            # Both alphanumeric, compare ASCII
            if p1 > p2:
                return 1
            elif p1 < p2:
                return -1

    # If all shared identifiers are equal, the one with fewer identifiers is lower
    if len(parts1) > len(parts2):
        return 1
    elif len(parts1) < len(parts2):
        return -1
    else:
        return 0


def _satisfies_caret(version, version_req):
    """Check if version satisfies ^version_req."""
    # Parse the required version
    req_parsed = _parse_version(version_req)
    major = req_parsed[0]
    minor = req_parsed[1]
    patch = req_parsed[2]
    prerelease = req_parsed[3]

    # Parse the actual version
    version_parsed = _parse_version(version)
    v_major = version_parsed[0]
    v_minor = version_parsed[1]
    v_patch = version_parsed[2]
    v_prerelease = version_parsed[3]

    # Check if version is less than required
    if _compare_versions(version, version_req) < 0:
        return False

    # Check if version is within the caret range
    if major > 0:
        # ^X.Y.Z means >= X.Y.Z and < (X+1).0.0
        if v_major > major:
            return False
        # If same major, it's valid (since we already checked >=)
        return True
    elif minor > 0:
        # ^0.Y.Z means >= 0.Y.Z and < 0.(Y+1).0
        if v_major > 0:
            return False
        if v_major < 0:
            return True
        # Same major (0), check minor
        if v_minor > minor:
            return False
        # If same major (0) and minor, it's valid (since we already checked >=)
        return True
    else:
        # ^0.0.Z means >= 0.0.Z and < 0.0.(Z+1)
        if v_major > 0:
            return False
        if v_major < 0:
            return True
        if v_minor > 0:
            return False
        # If same major (0) and minor (0), check patch
        if v_patch > patch:
            return False
        # If same major (0), minor (0), and patch, it's valid (since we already checked >=)
        return True


def _satisfies_tilde(version, version_req):
    """Check if version satisfies ~version_req."""
    # Parse the required version
    req_parsed = _parse_version(version_req)
    major = req_parsed[0]
    minor = req_parsed[1]
    patch = req_parsed[2]
    prerelease = req_parsed[3]

    # Parse the actual version
    version_parsed = _parse_version(version)
    v_major = version_parsed[0]
    v_minor = version_parsed[1]
    v_patch = version_parsed[2]
    v_prerelease = version_parsed[3]

    # Check if version is less than required
    if _compare_versions(version, version_req) < 0:
        return False

    # Check if version is within the tilde range
    if v_major > major:
        return False
    if v_major < major:
        return True

    # Same major, check minor
    if v_minor > minor:
        return False
    # If same major and minor, it's valid (since we already checked >=)
    return True

