from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    # Parse the cron expression
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Invalid cron expression: must have exactly 5 fields")

    try:
        minute_expr = parse_field(fields[0], 0, 59)
        hour_expr = parse_field(fields[1], 0, 23)
        day_expr = parse_field(fields[2], 1, 31)
        month_expr = parse_field(fields[3], 1, 12)
        dow_expr = parse_field(fields[4], 0, 7)
    except ValueError:
        raise ValueError("Invalid cron expression")

    # Check if both day-of-month and day-of-week are restricted
    day_of_month_restricted = not is_unrestricted(fields[2])
    day_of_week_restricted = not is_unrestricted(fields[4])

    # Start searching from the next minute after 'after'
    current = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # Limit search to 3000 days
    max_time = after + timedelta(days=3000)

    while current <= max_time:
        # Check if current datetime matches all fields
        if (matches_field(current.minute, minute_expr) and
            matches_field(current.hour, hour_expr) and
            matches_field(current.day, day_expr) and
            matches_field(current.month, month_expr) and
            matches_field(current.weekday() if current.weekday() != 0 else 7, dow_expr)):

            # Special handling for day-of-month and day-of-week
            if day_of_month_restricted and day_of_week_restricted:
                # Either day-of-month or day-of-week must match
                if (matches_field(current.day, day_expr) or 
                    matches_field(current.weekday() if current.weekday() != 0 else 7, dow_expr)):
                    return current
            else:
                # Both must match
                if (matches_field(current.day, day_expr) and 
                    matches_field(current.weekday() if current.weekday() != 0 else 7, dow_expr)):
                    return current

        # Move to next minute
        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 3000 days")


def parse_field(field, min_val, max_val):
    """Parse a cron field into a list of valid values."""
    if not field:
        raise ValueError("Empty field")

    values = set()

    for item in field.split(','):
        if not item:
            raise ValueError("Empty item")

        # Handle step notation
        if '/' in item:
            base, step_str = item.split('/')
            if not step_str.isdigit() or int(step_str) < 1:
                raise ValueError("Invalid step value")
            step = int(step_str)

            if base == '*':
                # */S: start from min_val, step by S
                for val in range(min_val, max_val + 1, step):
                    values.add(val)
            else:
                # N/S: start from N, step by S
                try:
                    base_val = int(base)
                except ValueError:
                    raise ValueError("Invalid base value")
                if base_val < min_val or base_val > max_val:
                    raise ValueError("Base value out of range")
                for val in range(base_val, max_val + 1, step):
                    values.add(val)
        else:
            # Handle range notation
            if '-' in item:
                start_str, end_str = item.split('-')
                if not start_str.isdigit() or not end_str.isdigit():
                    raise ValueError("Invalid range")
                start = int(start_str)
                end = int(end_str)
                if start > end:
                    raise ValueError("Start of range greater than end")
                for val in range(start, end + 1):
                    values.add(val)
            elif item == '*':
                # All values in range
                for val in range(min_val, max_val + 1):
                    values.add(val)
            else:
                # Single value
                try:
                    val = int(item)
                except ValueError:
                    raise ValueError("Invalid value")
                if val < min_val or val > max_val:
                    raise ValueError("Value out of range")
                values.add(val)

    return sorted(list(values))


def matches_field(value, field_values):
    """Check if a value matches a field."""
    return value in field_values


def is_unrestricted(field):
    """Check if a field is unrestricted (i.e., '*')."""
    return field == '*'

