class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ('0' is fine). '-' means 'past the
    end of the list' and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    # Create a deep copy of the document to avoid modifying the original
    import copy
    result = copy.deepcopy(doc)

    # Process each operation in order
    for op in ops:
        # Validate operation structure
        if "op" not in op:
            raise PatchError("Operation missing 'op' field")
        if "path" not in op:
            raise PatchError("Operation missing 'path' field")

        op_type = op["op"]
        path = op["path"]

        # Parse path
        tokens = _parse_path(path)

        # Handle each operation type
        if op_type == "add":
            if "value" not in op:
                raise PatchError("Add operation missing 'value' field")
            _add(result, tokens, op["value"])
        elif op_type == "remove":
            if not tokens:
                raise PatchError("Cannot remove root document")
            _remove(result, tokens)
        elif op_type == "replace":
            if "value" not in op:
                raise PatchError("Replace operation missing 'value' field")
            _replace(result, tokens, op["value"])
        elif op_type == "move":
            if "from" not in op:
                raise PatchError("Move operation missing 'from' field")
            from_tokens = _parse_path(op["from"])
            _move(result, from_tokens, tokens)
        elif op_type == "copy":
            if "from" not in op:
                raise PatchError("Copy operation missing 'from' field")
            from_tokens = _parse_path(op["from"])
            _copy(result, from_tokens, tokens)
        elif op_type == "test":
            if "value" not in op:
                raise PatchError("Test operation missing 'value' field")
            _test(result, tokens, op["value"])
        else:
            raise PatchError(f"Unknown operation: {op_type}")

    return result


def _parse_path(path):
    """Parse a JSON pointer path into tokens."""
    if path == "":
        return []

    if not path.startswith("/"):
        raise PatchError(f"Invalid path: {path}")

    # Split path by '/' and remove empty first element
    parts = path.split("/")[1:]

    # Process escape sequences
    tokens = []
    for part in parts:
        # Replace ~1 with / and ~0 with ~
        part = part.replace("~1", "/").replace("~0", "~")
        # Check for invalid ~ sequences
        if "~" in part:
            raise PatchError(f"Invalid escape sequence in path: {path}")
        tokens.append(part)

    return tokens


def _get_value_at_path(obj, tokens):
    """Get the value at the given path."""
    current = obj
    for token in tokens:
        if isinstance(current, list):
            if token == "-":
                raise PatchError("Cannot use '-' in path for getting values")
            try:
                index = int(token)
                if index < 0:
                    raise PatchError("Negative indices not allowed")
                # Check for leading zeros (except for "0")
                if token != "0" and token.startswith("0") and len(token) > 1:
                    raise PatchError(f"Invalid index with leading zero: {token}")
                current = current[index]
            except (ValueError, IndexError):
                raise PatchError(f"Invalid index: {token}")
        elif isinstance(current, dict):
            if token not in current:
                raise PatchError(f"Key not found: {token}")
            current = current[token]
        else:
            raise PatchError(f"Cannot navigate into {type(current)}")
    return current


def _set_value_at_path(obj, tokens, value):
    """Set the value at the given path."""
    if not tokens:
        # Setting the root document
        return value

    current = obj
    for token in tokens[:-1]:
        if isinstance(current, list):
            try:
                index = int(token)
                if index < 0:
                    raise PatchError("Negative indices not allowed")
                # Check for leading zeros (except for "0")
                if token != "0" and token.startswith("0") and len(token) > 1:
                    raise PatchError(f"Invalid index with leading zero: {token}")
                current = current[index]
            except (ValueError, IndexError):
                raise PatchError(f"Invalid index: {token}")
        elif isinstance(current, dict):
            if token not in current:
                raise PatchError(f"Key not found: {token}")
            current = current[token]
        else:
            raise PatchError(f"Cannot navigate into {type(current)}")

    # Set the final value
    final_token = tokens[-1]
    if isinstance(current, list):
        try:
            index = int(final_token)
            if index < 0:
                raise PatchError("Negative indices not allowed")
            # Check for leading zeros (except for "0")
            if final_token != "0" and final_token.startswith("0") and len(final_token) > 1:
                raise PatchError(f"Invalid index with leading zero: {final_token}")
            if index == len(current):
                current.append(value)
            elif index > len(current):
                raise PatchError(f"Index out of range: {index}")
            else:
                current.insert(index, value)
        except ValueError:
            if final_token == "-":
                current.append(value)
            else:
                raise PatchError(f"Invalid index: {final_token}")
    elif isinstance(current, dict):
        current[final_token] = value
    else:
        raise PatchError(f"Cannot set value in {type(current)}")

    return obj


def _remove_value_at_path(obj, tokens):
    """Remove the value at the given path."""
    if not tokens:
        raise PatchError("Cannot remove root document")

    current = obj
    for token in tokens[:-1]:
        if isinstance(current, list):
            try:
                index = int(token)
                if index < 0:
                    raise PatchError("Negative indices not allowed")
                # Check for leading zeros (except for "0")
                if token != "0" and token.startswith("0") and len(token) > 1:
                    raise PatchError(f"Invalid index with leading zero: {token}")
                current = current[index]
            except (ValueError, IndexError):
                raise PatchError(f"Invalid index: {token}")
        elif isinstance(current, dict):
            if token not in current:
                raise PatchError(f"Key not found: {token}")
            current = current[token]
        else:
            raise PatchError(f"Cannot navigate into {type(current)}")

    # Remove the final value
    final_token = tokens[-1]
    if isinstance(current, list):
        try:
            index = int(final_token)
            if index < 0:
                raise PatchError("Negative indices not allowed")
            # Check for leading zeros (except for "0")
            if final_token != "0" and final_token.startswith("0") and len(final_token) > 1:
                raise PatchError(f"Invalid index with leading zero: {final_token}")
            if index >= len(current):
                raise PatchError(f"Index out of range: {index}")
            current.pop(index)
        except ValueError:
            raise PatchError(f"Invalid index: {final_token}")
    elif isinstance(current, dict):
        if final_token not in current:
            raise PatchError(f"Key not found: {final_token}")
        del current[final_token]
    else:
        raise PatchError(f"Cannot remove value from {type(current)}")


def _add(obj, tokens, value):
    """Add a value at the given path."""
    if not tokens:
        # Adding to root - replace the whole document
        return value

    # Check if parent exists
    parent_tokens = tokens[:-1]
    if parent_tokens:
        try:
            _get_value_at_path(obj, parent_tokens)
        except PatchError:
            raise PatchError("Parent container does not exist")

    # Add the value
    return _set_value_at_path(obj, tokens, value)


def _remove(obj, tokens):
    """Remove a value at the given path."""
    _remove_value_at_path(obj, tokens)


def _replace(obj, tokens, value):
    """Replace a value at the given path."""
    # Check if target exists
    try:
        _get_value_at_path(obj, tokens)
    except PatchError:
        raise PatchError("Target does not exist")

    # Replace the value
    if not tokens:
        # Replacing root - replace the whole document
        return value

    # Navigate to parent and set the value
    parent_tokens = tokens[:-1]
    if parent_tokens:
        parent = _get_value_at_path(obj, parent_tokens)
        final_token = tokens[-1]
        if isinstance(parent, list):
            try:
                index = int(final_token)
                if index < 0:
                    raise PatchError("Negative indices not allowed")
                # Check for leading zeros (except for "0")
                if final_token != "0" and final_token.startswith("0") and len(final_token) > 1:
                    raise PatchError(f"Invalid index with leading zero: {final_token}")
                if index >= len(parent):
                    raise PatchError(f"Index out of range: {index}")
                parent[index] = value
            except ValueError:
                raise PatchError(f"Invalid index: {final_token}")
        elif isinstance(parent, dict):
            parent[final_token] = value
        else:
            raise PatchError(f"Cannot set value in {type(parent)}")
    else:
        # Root replacement
        return value


def _move(obj, from_tokens, to_tokens):
    """Move a value from one path to another."""
    # Check if source exists
    try:
        value = _get_value_at_path(obj, from_tokens)
    except PatchError:
        raise PatchError("Source does not exist")

    # Check if target path is inside source path (invalid)
    if len(from_tokens) < len(to_tokens):
        # Check if to_tokens starts with from_tokens
        if to_tokens[:len(from_tokens)] == from_tokens:
            # Check if the remaining part is not just the final token
            if len(to_tokens) > len(from_tokens) or to_tokens[len(from_tokens)] != "":
                raise PatchError("Target path lies inside source path")

    # Remove from source
    _remove_value_at_path(obj, from_tokens)

    # Add to destination
    _set_value_at_path(obj, to_tokens, value)


def _copy(obj, from_tokens, to_tokens):
    """Copy a value from one path to another."""
    # Check if source exists
    try:
        value = _get_value_at_path(obj, from_tokens)
    except PatchError:
        raise PatchError("Source does not exist")

    # Add to destination
    _set_value_at_path(obj, to_tokens, value)


def _test(obj, tokens, value):
    """Test that a value at a path equals the expected value."""
    try:
        actual = _get_value_at_path(obj, tokens)
    except PatchError:
        raise PatchError("Target does not exist")

    # Deep equality check
    if not _deep_equal(actual, value):
        raise PatchError("Test failed: values do not match")


def _deep_equal(a, b):
    """Check if two values are deeply equal."""
    if type(a) != type(b):
        return False

    if isinstance(a, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(_deep_equal(a[key], b[key]) for key in a.keys())
    elif isinstance(a, list):
        if len(a) != len(b):
            return False
        return all(_deep_equal(a[i], b[i]) for i in range(len(a)))
    else:
        # For primitive types, use direct comparison
        # Handle special case for numbers (1 == 1.0)
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return a == b
        return a == b

