def glob_match(pattern, path):
    """Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    # Split pattern and path into segments
    pattern_segments = pattern.split('/')
    path_segments = path.split('/')

    # Handle the matching with proper ** logic
    return match_segments(pattern_segments, path_segments, 0, 0)


def match_segments(pattern_segments, path_segments, p_idx, s_idx):
    """Recursively match pattern segments with path segments."""
    # If we've consumed all pattern segments
    if p_idx >= len(pattern_segments):
        # We should also have consumed all path segments
        return s_idx >= len(path_segments)

    # If we've consumed all path segments but still have pattern segments
    if s_idx >= len(path_segments):
        # Check if remaining pattern segments are all "**"
        for i in range(p_idx, len(pattern_segments)):
            if pattern_segments[i] != '**':
                return False
        return True

    pattern_segment = pattern_segments[p_idx]
    path_segment = path_segments[s_idx]

    # Handle "**" pattern segment
    if pattern_segment == '**':
        # "**" matches zero or more path segments
        # Try to match the rest of the pattern with the rest of the path
        # This is a greedy approach - we try to match as much as possible

        # If "**" is the last pattern segment, it matches everything
        if p_idx == len(pattern_segments) - 1:
            return True

        # Otherwise, try to find a match for the next pattern segment
        # by skipping path segments
        next_pattern_segment = pattern_segments[p_idx + 1]
        # Try to match next_pattern_segment with each remaining path segment
        for i in range(s_idx, len(path_segments)):
            if match_single_segment(next_pattern_segment, path_segments[i]):
                # Found a match, continue with the next pattern segment
                if match_segments(pattern_segments, path_segments, p_idx + 2, i + 1):
                    return True
        # No match found
        return False

    # Handle regular pattern segment
    if match_single_segment(pattern_segment, path_segment):
        return match_segments(pattern_segments, path_segments, p_idx + 1, s_idx + 1)

    return False


def match_single_segment(pattern, segment):
    """Match a single pattern against a single segment."""
    if not pattern:
        return not segment

    # Handle special characters in pattern
    i = 0
    j = 0

    while i < len(pattern) and j < len(segment):
        char = pattern[i]

        if char == '*':
            # Find the next non-* character in pattern
            while i < len(pattern) and pattern[i] == '*':
                i += 1
            if i == len(pattern):
                # Pattern ends with "*", so it matches any segment
                return True
            # Find the next occurrence of the next pattern character in segment
            next_char = pattern[i]
            # Skip characters in segment until we find next_char or reach end
            while j < len(segment):
                if segment[j] == next_char:
                    # Found the next character, try to match the rest
                    return match_single_segment(pattern[i:], segment[j:])
                j += 1
            # No match found
            return False
        elif char == '?':
            # "?" matches any single character except "/"
            if segment[j] == '/':
                return False
            i += 1
            j += 1
        elif char == '[':
            # Handle character set
            # Find the matching ']'
            end_bracket = pattern.find(']', i)
            if end_bracket == -1:
                raise ValueError("unterminated [")

            # Extract the set
            set_content = pattern[i+1:end_bracket]

            # Check if it's a negated set
            negated = False
            if set_content.startswith('!'):
                negated = True
                set_content = set_content[1:]

            # Check if the current character matches the set
            char_match = False
            if j < len(segment):
                char_to_match = segment[j]
                if char_to_match == '/':
                    char_match = False
                else:
                    char_match = char_in_set(char_to_match, set_content)

            if negated:
                char_match = not char_match

            if not char_match:
                return False

            i = end_bracket + 1
            j += 1
        elif char == '\\':
            # Handle escaped character
            if i + 1 < len(pattern):
                escaped_char = pattern[i+1]
                if j < len(segment) and segment[j] == escaped_char:
                    i += 2
                    j += 1
                else:
                    return False
            else:
                # Trailing backslash
                raise ValueError("trailing backslash")
        else:
            # Regular character matching
            if j < len(segment) and segment[j] == char:
                i += 1
                j += 1
            else:
                return False

    # Check if we've consumed the entire pattern and segment
    if i < len(pattern):
        # Check if remaining pattern is all "*"
        while i < len(pattern) and pattern[i] == '*':
            i += 1
        if i < len(pattern):
            return False
    if j < len(segment):
        return False

    return True


def char_in_set(char, set_content):
    """Check if a character is in a character set."""
    # Special case: if the first character is ']' or '-', it's literal
    i = 0
    while i < len(set_content):
        if set_content[i] == ']':
            # ']' is literal when it's the first character in the set
            if i == 0:
                if char == ']':
                    return True
                i += 1
                continue
            # Otherwise, it's a normal character in the set
            if char == ']':
                return True
            i += 1
        elif set_content[i] == '-':
            # '-' is literal when it's first or last in the set
            if i == 0 or i == len(set_content) - 1:
                if char == '-':
                    return True
                i += 1
                continue
            # Check for range
            if i + 2 < len(set_content) and set_content[i+1] == '-' and set_content[i+2] != ']':
                # Range: check if char is between the two characters
                if set_content[i-1] <= char <= set_content[i+2]:
                    return True
                i += 3
                continue
            # Otherwise, it's a literal '-'
            if char == '-':
                return True
            i += 1
        elif i + 2 < len(set_content) and set_content[i+1] == '-':
            # Range: check if char is between the two characters
            if set_content[i] <= char <= set_content[i+2]:
                return True
            i += 3
        else:
            # Single character
            if set_content[i] == char:
                return True
            i += 1
    return False

