def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    # Parse the range into comparator sets
    if not rng.strip():
        raise ValueError("Invalid range")

    # Split by || and trim whitespace
    sets = [s.strip() for s in rng.split("||")]

    # Validate that no set is empty
    for s in sets:
        if not s:
            raise ValueError("Invalid range")

    # Check if any set satisfies the version
    for set_str in sets:
        # Parse the set into individual comparators
        comparators = set_str.split()
        if not comparators:
            raise ValueError("Invalid range")

        # Check if all comparators in this set are satisfied
        set_satisfied = True
        for comp in comparators:
            if not _satisfies_comparator(version, comp):
                set_satisfied = False
                break

        if set_satisfied:
            return True

    return False


def _satisfies_comparator(version, comparator):
    # Parse comparator
    if comparator.startswith(">="):
        op = ">="
        ver = comparator[2:]
    elif comparator.startswith("<="):
        op = "<="
        ver = comparator[2:]
    elif comparator.startswith(">"):
        op = ">"
        ver = comparator[1:]
    elif comparator.startswith("<"):
        op = "<"
        ver = comparator[1:]
    elif comparator.startswith("^"):
        op = "^"
        ver = comparator[1:]
    elif comparator.startswith("~"):
        op = "~"
        ver = comparator[1:]
    elif comparator.startswith("="):
        op = "="
        ver = comparator[1:]
    else:
        # No operator means equals
        op = "="
        ver = comparator

    # Validate version
    _validate_version(ver)

    # Compare versions
    if op == "=":
        return _compare_versions(version, ver) == 0
    elif op == ">":
        return _compare_versions(version, ver) > 0
    elif op == ">=":
        return _compare_versions(version, ver) >= 0
    elif op == "<":
        return _compare_versions(version, ver) < 0
    elif op == "<=":
        return _compare_versions(version, ver) <= 0
    elif op == "^":
        return _satisfies_caret(version, ver)
    elif op == "~":
        return _satisfies_tilde(version, ver)

    return False


def _satisfies_caret(version, ver):
    # Parse version
    major, minor, patch, prerelease = _parse_version(ver)

    # For caret, we need to check if version is >= ver and < next significant version
    # If major > 0, then next significant version is (major+1).0.0
    # If major == 0 and minor > 0, then next significant version is 0.(minor+1).0
    # If major == 0 and minor == 0, then next significant version is 0.0.(patch+1)

    # Check if version is >= ver
    if _compare_versions(version, ver) < 0:
        return False

    # Determine upper bound
    if major > 0:
        upper_bound = f"{major + 1}.0.0"
    elif minor > 0:
        upper_bound = f"0.{minor + 1}.0"
    else:
        upper_bound = f"0.0.{patch + 1}"

    # Check if version is < upper_bound
    return _compare_versions(version, upper_bound) < 0


def _satisfies_tilde(version, ver):
    # Parse version
    major, minor, patch, prerelease = _parse_version(ver)

    # For tilde, we need to check if version is >= ver and < major.(minor+1).0
    # Check if version is >= ver
    if _compare_versions(version, ver) < 0:
        return False

    # Upper bound is major.(minor+1).0
    upper_bound = f"{major}.{minor + 1}.0"

    # Check if version is < upper_bound
    return _compare_versions(version, upper_bound) < 0


def _compare_versions(v1, v2):
    # Parse versions
    major1, minor1, patch1, prerelease1 = _parse_version(v1)
    major2, minor2, patch2, prerelease2 = _parse_version(v2)

    # Compare major
    if major1 > major2:
        return 1
    elif major1 < major2:
        return -1

    # Compare minor
    if minor1 > minor2:
        return 1
    elif minor1 < minor2:
        return -1

    # Compare patch
    if patch1 > patch2:
        return 1
    elif patch1 < patch2:
        return -1

    # If both have prerelease, compare them
    if prerelease1 and prerelease2:
        return _compare_prerelease(prerelease1, prerelease2)
    elif prerelease1:
        # v1 has prerelease, v2 doesn't -> v1 < v2 (prerelease versions are lower)
        return -1
    elif prerelease2:
        # v2 has prerelease, v1 doesn't -> v1 > v2 (prerelease versions are lower)
        return 1
    else:
        # Neither has prerelease
        return 0


def _compare_prerelease(pr1, pr2):
    # Split prerelease identifiers
    parts1 = pr1.split(".")
    parts2 = pr2.split(".")

    # Compare each part
    min_len = min(len(parts1), len(parts2))
    for i in range(min_len):
        p1 = parts1[i]
        p2 = parts2[i]

        # Check if both are numeric
        is_num1 = p1.isdigit()
        is_num2 = p2.isdigit()

        if is_num1 and is_num2:
            # Both numeric, compare numerically
            num1 = int(p1)
            num2 = int(p2)
            if num1 > num2:
                return 1
            elif num1 < num2:
                return -1
        elif is_num1:
            # p1 is numeric, p2 is not -> p1 < p2 (numeric comes before alphanumeric)
            return -1
        elif is_num2:
            # p2 is numeric, p1 is not -> p1 > p2 (numeric comes before alphanumeric)
            return 1
        else:
            # Both non-numeric, compare ASCII
            if p1 > p2:
                return 1
            elif p1 < p2:
                return -1

    # If all shared parts are equal, the one with fewer parts is lower
    if len(parts1) > len(parts2):
        return 1
    elif len(parts1) < len(parts2):
        return -1
    else:
        return 0


def _parse_version(version):
    # Split version into parts
    if "+" in version:
        raise ValueError("Build metadata not allowed")

    if "-" in version:
        main, prerelease = version.split("-", 1)
    else:
        main = version
        prerelease = None

    # Split main version
    parts = main.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid version")

    major = int(parts[0])
    minor = int(parts[1])
    patch = int(parts[2])

    # Validate numeric parts
    if major < 0 or minor < 0 or patch < 0:
        raise ValueError("Invalid version")

    # Validate no leading zeros
    if parts[0] != "0" and parts[0].startswith("0"):
        raise ValueError("Invalid version")
    if parts[1] != "0" and parts[1].startswith("0"):
        raise ValueError("Invalid version")
    if parts[2] != "0" and parts[2].startswith("0"):
        raise ValueError("Invalid version")

    return major, minor, patch, prerelease


def _validate_version(version):
    # Validate version format
    if not version:
        raise ValueError("Invalid version")

    # Check for build metadata
    if "+" in version:
        raise ValueError("Build metadata not allowed")

    # Check for valid prerelease format
    if "-" in version:
        main, prerelease = version.split("-", 1)
        if not prerelease:
            raise ValueError("Invalid version")

        # Check each prerelease identifier
        for part in prerelease.split("."):
            if not part:
                raise ValueError("Invalid version")
            # Check if part contains only valid characters
            for c in part:
                if not (c.isdigit() or c.isalpha() or c == "-"):
                    raise ValueError("Invalid version")
    else:
        main = version

    # Check main version format
    parts = main.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid version")

    # Validate each part is a valid non-negative integer without leading zeros
    for i, part in enumerate(parts):
        if not part.isdigit():
            raise ValueError("Invalid version")
        if part != "0" and part.startswith("0"):
            raise ValueError("Invalid version")
        if int(part) < 0:
            raise ValueError("Invalid version")

