class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    # Create a deep copy of the document to avoid modifying the original
    import copy
    result = copy.deepcopy(doc)

    # Process each operation
    for op in ops:
        if 'op' not in op:
            raise PatchError("Missing 'op' in operation")
        if 'path' not in op:
            raise PatchError("Missing 'path' in operation")

        op_type = op['op']
        path = op['path']

        if op_type == 'add':
            if 'value' not in op:
                raise PatchError("Missing 'value' in add operation")
            value = op['value']
            _apply_add(result, path, value)
        elif op_type == 'remove':
            _apply_remove(result, path)
        elif op_type == 'replace':
            if 'value' not in op:
                raise PatchError("Missing 'value' in replace operation")
            value = op['value']
            _apply_replace(result, path, value)
        elif op_type == 'move':
            if 'from' not in op:
                raise PatchError("Missing 'from' in move operation")
            from_path = op['from']
            _apply_move(result, from_path, path)
        elif op_type == 'copy':
            if 'from' not in op:
                raise PatchError("Missing 'from' in copy operation")
            from_path = op['from']
            _apply_copy(result, from_path, path)
        elif op_type == 'test':
            if 'value' not in op:
                raise PatchError("Missing 'value' in test operation")
            value = op['value']
            _apply_test(result, path, value)
        else:
            raise PatchError(f"Unknown operation: {op_type}")

    return result


def _parse_path(path):
    """Parse a JSON pointer path into tokens."""
    if path == "":
        return []
    if not path.startswith("/"):
        raise PatchError("Invalid path: must start with '/'")

    # First, validate escape sequences
    # Check for invalid ~ sequences (not ~0 or ~1)
    for i in range(len(path)):
        if path[i] == "~":
            if i + 1 >= len(path):
                raise PatchError("Invalid escape sequence in path")
            if path[i+1] not in "01":
                raise PatchError("Invalid escape sequence in path")

    tokens = path[1:].split("/")
    # Handle empty tokens (e.g., "/a//b" -> ["a", "", "b"])
    # But also handle escaped characters
    result = []
    for token in tokens:
        # Unescape ~1 to / and ~0 to ~
        token = token.replace("~1", "/").replace("~0", "~")
        result.append(token)
    return result


def _get_value_at_path(obj, path_tokens):
    """Get the value at the given path."""
    current = obj
    for token in path_tokens:
        if isinstance(current, list):
            try:
                index = int(token)
                if index < 0:
                    raise PatchError("Invalid index in path")
                current = current[index]
            except (ValueError, IndexError):
                raise PatchError("Path does not exist")
        elif isinstance(current, dict):
            if token not in current:
                raise PatchError("Path does not exist")
            current = current[token]
        else:
            raise PatchError("Path does not exist")
    return current


def _set_value_at_path(obj, path_tokens, value):
    """Set the value at the given path."""
    if not path_tokens:
        # Setting the root
        return value

    current = obj
    for token in path_tokens[:-1]:
        if isinstance(current, list):
            try:
                index = int(token)
                if index < 0:
                    raise PatchError("Invalid index in path")
                current = current[index]
            except (ValueError, IndexError):
                raise PatchError("Path does not exist")
        elif isinstance(current, dict):
            if token not in current:
                raise PatchError("Path does not exist")
            current = current[token]
        else:
            raise PatchError("Path does not exist")

    last_token = path_tokens[-1]
    if isinstance(current, list):
        try:
            index = int(last_token)
            if index < 0:
                raise PatchError("Invalid index in path")
            current.insert(index, value)
        except ValueError:
            raise PatchError("Invalid index in path")
    elif isinstance(current, dict):
        current[last_token] = value
    else:
        raise PatchError("Path does not exist")
    return obj


def _remove_value_at_path(obj, path_tokens):
    """Remove the value at the given path."""
    if not path_tokens:
        raise PatchError("Cannot remove root")

    current = obj
    for token in path_tokens[:-1]:
        if isinstance(current, list):
            try:
                index = int(token)
                if index < 0:
                    raise PatchError("Invalid index in path")
                current = current[index]
            except (ValueError, IndexError):
                raise PatchError("Path does not exist")
        elif isinstance(current, dict):
            if token not in current:
                raise PatchError("Path does not exist")
            current = current[token]
        else:
            raise PatchError("Path does not exist")

    last_token = path_tokens[-1]
    if isinstance(current, list):
        try:
            index = int(last_token)
            if index < 0:
                raise PatchError("Invalid index in path")
            del current[index]
        except (ValueError, IndexError):
            raise PatchError("Path does not exist")
    elif isinstance(current, dict):
        if last_token not in current:
            raise PatchError("Path does not exist")
        del current[last_token]
    else:
        raise PatchError("Path does not exist")


def _is_valid_list_index(token):
    """Check if a token is a valid list index."""
    if token == "-":
        return True
    if token == "0":
        return True
    if token.startswith("0") and len(token) > 1:
        return False  # Leading zeros are not allowed
    try:
        index = int(token)
        return index >= 0
    except ValueError:
        return False


def _apply_add(doc, path, value):
    """Apply an add operation."""
    tokens = _parse_path(path)
    if not tokens:
        # Adding to root replaces the whole document
        return value

    parent_tokens = tokens[:-1]
    last_token = tokens[-1]

    # Check if parent exists
    try:
        parent = _get_value_at_path(doc, parent_tokens)
    except PatchError:
        raise PatchError("Parent container does not exist")

    # Validate the last token
    if isinstance(parent, list):
        if last_token == "-":
            parent.append(value)
        elif _is_valid_list_index(last_token):
            try:
                index = int(last_token)
                if index > len(parent):
                    raise PatchError("Index out of bounds")
                parent.insert(index, value)
            except ValueError:
                raise PatchError("Invalid index in path")
        else:
            raise PatchError("Invalid index in path")
    elif isinstance(parent, dict):
        parent[last_token] = value
    else:
        raise PatchError("Parent container does not exist")


def _apply_remove(doc, path):
    """Apply a remove operation."""
    tokens = _parse_path(path)
    _remove_value_at_path(doc, tokens)


def _apply_replace(doc, path, value):
    """Apply a replace operation."""
    tokens = _parse_path(path)
    if not tokens:
        # Replacing root replaces the whole document
        return value

    parent_tokens = tokens[:-1]
    last_token = tokens[-1]

    # Check if parent exists
    try:
        parent = _get_value_at_path(doc, parent_tokens)
    except PatchError:
        raise PatchError("Path does not exist")

    # Validate the last token
    if isinstance(parent, list):
        try:
            index = int(last_token)
            if index < 0:
                raise PatchError("Invalid index in path")
            parent[index] = value
        except (ValueError, IndexError):
            raise PatchError("Path does not exist")
    elif isinstance(parent, dict):
        if last_token not in parent:
            raise PatchError("Path does not exist")
        parent[last_token] = value
    else:
        raise PatchError("Path does not exist")


def _apply_move(doc, from_path, to_path):
    """Apply a move operation."""
    from_tokens = _parse_path(from_path)
    to_tokens = _parse_path(to_path)

    # Check if from path exists
    try:
        value = _get_value_at_path(doc, from_tokens)
    except PatchError:
        raise PatchError("Source path does not exist")

    # Check if to path would be inside from path (proper descendant)
    if len(to_tokens) > len(from_tokens):
        is_descendant = True
        for i in range(len(from_tokens)):
            if to_tokens[i] != from_tokens[i]:
                is_descendant = False
                break
        if is_descendant and to_tokens[len(from_tokens)] != "-":
            raise PatchError("Target path cannot be inside source path")

    # Remove from source
    _remove_value_at_path(doc, from_tokens)

    # Add to destination
    _apply_add(doc, to_path, value)


def _apply_copy(doc, from_path, to_path):
    """Apply a copy operation."""
    from_tokens = _parse_path(from_path)
    to_tokens = _parse_path(to_path)

    # Check if from path exists
    try:
        value = _get_value_at_path(doc, from_tokens)
    except PatchError:
        raise PatchError("Source path does not exist")

    # Add to destination
    _apply_add(doc, to_path, value)


def _apply_test(doc, path, value):
    """Apply a test operation."""
    tokens = _parse_path(path)
    try:
        actual_value = _get_value_at_path(doc, tokens)
    except PatchError:
        raise PatchError("Path does not exist")

    # Deep equality check
    if actual_value != value:
        raise PatchError("Test failed: values do not match")
